(9932, 896, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:18:\"Cappella Imperiale\";}s:2:\"fr\";a:1:{s:4:\"text\";s:19:\"Chapelle Impériale\";}}}'),
(9933, 896, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:190:\"Il cardinale Fesch, morto in esilio a Roma nel 1839, aveva stanziato fondi nel suo testamento per la costruzione di una cappella mortuaria dove lui e la sua famiglia potessero essere sepolti\";}s:2:\"fr\";a:1:{s:4:\"text\";s:196:\"Le cardinal Fesch, mort en exil à Rome en 1839, avait affecté dans son testament une somme pour la construction d\'une chapelle mortuaire pour y être enterré ainsi que les membres de sa famille\";}}}'),
(9934, 896, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:8:\"cappella\";}s:2:\"fr\";a:1:{s:4:\"text\";s:8:\"chapelle\";}}}'),
