(10013, 905, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:6:\"Chiesa\";}s:2:\"fr\";a:1:{s:4:\"text\";s:6:\"Eglise\";}}}'),
(10014, 905, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:246:\"Chiesa in stile barocco risalente alla metà del XVI secolo. Della chiesa originaria dell\'XI secolo rimangono solo l\'abside e il coro. La facciata, la navata e due cappelle laterali furono ricostruite nel 1538. Il campanile risale al XVII secolo.\";}s:2:\"fr\";a:1:{s:4:\"text\";s:249:\"Eglise de style baroque, datant du milieu du 16e siècle. Il ne reste de l\'église primitive du 11e siècle, que l\'abside et le choeur. La façade, la nef et les deux chapelles latérales ont été refaites en 1538. Le campanile date du 17e siècle.\";}}}'),
(10015, 905, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:6:\"chiesa\";}s:2:\"fr\";a:1:{s:4:\"text\";s:7:\"église\";}}}'),
