(10031, 907, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:31:\"Tomba dello scultore Maestracci\";}s:2:\"fr\";a:1:{s:4:\"text\";s:31:\"Tombeau du sculpteur Maestracci\";}}}'),
(10032, 907, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:164:\"La tomba fu realizzata dal pittore e scultore corso Maestracci nel 1928; moriÌ nel 1976. La tomba ha tre livelli separati da cornici ed è sormontata da una croce.\";}s:2:\"fr\";a:1:{s:4:\"text\";s:202:\"Le tombeau a été édifié par le peintre et sculpteur insulaire Maestracci, en 1928, qui est décédé en 1976. Le tombeau comporte trois niveaux séparés par des corniches. Il est sommé d\'une croix\";}}}'),
(10033, 907, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:5:\"tomba\";}s:2:\"fr\";a:1:{s:4:\"text\";s:7:\"tombeau\";}}}'),
