(10247, 931, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:19:\"Parco Santa Barbara\";}s:2:\"fr\";a:1:{s:4:\"text\";s:18:\"Parc Santa Barbara\";}}}'),
(10248, 931, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:273:\"Parco naturale ricco di numerose varietà di piante. Al suo interno si trovano resti archeologici. Il parco è dotato di un\'area attrezzata, ai margini della zona boschiva, dove si trovano un\'area giochi per bambini, un piccolo campo sportivo, panchine e due bar-ristoranti\";}s:2:\"fr\";a:1:{s:4:\"text\";s:264:\"Parc naturel riche en une grande variété de plantes. On y trouve des vestiges archéologiques. Le parc dispose d\'une aire aménagée, en bordure de la zone boisée, avec une aire de jeux pour enfants, un petit terrain de sport, des bancs et deux bars-restaurants\";}}}'),
(10249, 931, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:22:\"elemento naturalistico\";}s:2:\"fr\";a:1:{s:4:\"text\";s:21:\"élément naturaliste\";}}}');
