(10733, 985, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:40:\"Museo etnografico: La Terra e la Memoria\";}s:2:\"fr\";a:1:{s:4:\"text\";s:47:\"Musée ethnographique : La terre et la mémoire\";}}}'),
(10734, 985, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:197:\"Il museo presenta la vita contadina tradizionale dell\'Ottocento a Pigna e nell\'Alta Val Nervia, con uno spaccato della vita dei pastori, dei contadini e degli artigiani, con gli attrezzi dell\'epoca\";}s:2:\"fr\";a:1:{s:4:\"text\";s:216:\"Le musée présente la vie paysanne traditionnelle du XIXe siècle à Pigna et dans l\'Alta Val Nervia, offrant un aperçu du quotidien des bergers, des agriculteurs et des artisans, à travers les outils de l\'époque\";}}}'),
(10735, 985, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:6:\"Museo \";}s:2:\"fr\";a:1:{s:4:\"text\";s:7:\" Musée\";}}}'),
