(10742, 986, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:23:\"Museo Clarence Bicknell\";}s:2:\"fr\";a:1:{s:4:\"text\";s:24:\"Musée Clarence Bicknell\";}}}'),
(10743, 986, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:235:\"Il museo ospita molte delle collezioni create dallo studioso e una vasta biblioteca. I due giganteschi ficus all\'esterno sono particolari e affascinanti, parte di un lussureggiante giardino che abbraccia questo angolo di pace e rifugio\";}s:2:\"fr\";a:1:{s:4:\"text\";s:285:\"Le musée abrite de nombreuses collections constituées par l\'érudit ainsi qu\'une vaste bibliothèque. Les deux ficus gigantesques qui se dressent à l\'extérieur sont remarquables et fascinants ; ils font partie d\'un jardin luxuriant qui enveloppe ce havre de paix et de sérénité\";}}}'),
(10744, 986, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:10:\"Monumento \";}s:2:\"fr\";a:1:{s:4:\"text\";s:9:\" Monument\";}}}'),
