(10832, 996, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:39:\"La Cattedrale di Nostra Signora Assunta\";}s:2:\"fr\";a:1:{s:4:\"text\";s:41:\"La cathédrale Notre-Dame de l\'Assomption\";}}}'),
(10833, 996, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:239:\"La Cattedrale fu costruita nel XVI secolo per sostituire l\'antica struttura, posta sul promontorio del Priamar, che fu abbattuta da Genova per costruire una fortezza. La nuova Cattedrale fu costruita sull\'area della Chiesa di San Francesco\";}s:2:\"fr\";a:1:{s:4:\"text\";s:275:\"La cathédrale fut construite au XVIe siècle pour remplacer l\'ancienne structure, située sur le promontoire de Priamar, qui avait été démolie par Gênes pour y construire une forteresse. La nouvelle cathédrale fut érigée sur l\'emplacement de l\'église Saint-François\";}}}'),
(10834, 996, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:10:\"Monumento \";}s:2:\"fr\";a:1:{s:4:\"text\";s:9:\" Monument\";}}}'),
