(10859, 999, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:53:\"Museo Preistorico e Area Archeologica dei Balzi Rossi\";}s:2:\"fr\";a:1:{s:4:\"text\";s:56:\"Musée préhistorique et zone archéologique Balzi Rossi\";}}}'),
(10860, 999, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:257:\"Le Grotte dei Balzi Rossi sono una delle più straordinarie testimonianze della preistoria europea, un vero e proprio scrigno di storia che racconta l\'evoluzione dell\'uomo nel corso dei millenni. Situate ai piedi di una maestosa parete di calcare dolomitico\";}s:2:\"fr\";a:1:{s:4:\"text\";s:287:\"Les grottes de Balzi Rossi constituent l\'un des témoignages les plus extraordinaires de la préhistoire européenne, un véritable trésor historique qui retrace l\'évolution de l\'Homme au fil des millénaires. Elles sont situées au pied d\'une majestueuse paroi de calcaire dolomitique\";}}}'),
(10861, 999, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:6:\"Museo \";}s:2:\"fr\";a:1:{s:4:\"text\";s:7:\" Musée\";}}}'),
(10862, 999, 'additional_info', 'a:2:{s:9:\"date_text\";a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:201:\"Da martedì a domenica 8:30 - 19:30 Prima domenica del mese ingresso gratuito La Grotta del Caviglione è visitabile dalle 11:00 alle 12:00 e dalle 16:00 alle 17:00 (chiusa in caso di vento o maltempo)\";}s:2:\"fr\";a:1:{s:4:\"text\";s:196:\"Du mardi au dimanche, de 8h30 à 19h30. Entrée gratuite le premier dimanche du mois. La grotte de Caviglione se visite de 11h à 12h et de 16h à 17h. (Fermée en cas de vent ou de mauvais temps)\";}}}s:13:\"accessibility\";a:2:{s:5:\"label\";s:5:\"Media\";s:5:\"value\";s:1:\"2\";}}'),
