(10931, 1007, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:47:\"Museo Etnografico e della Stregoneria di Triora\";}s:2:\"fr\";a:1:{s:4:\"text\";s:49:\"Musée ethnographique et de sorcellerie de Triora\";}}}'),
(10932, 1007, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:136:\"Museo incentrato sulla vita rurale locale con sale dedicate alla stregoneria, di cui in passato furono accusati molti abitanti del paese\";}s:2:\"fr\";a:1:{s:4:\"text\";s:155:\"Musée axé sur la vie rurale locale, avec des salles consacrées à la sorcellerie, dont de nombreux habitants du village ont été accusés par le passé\";}}}'),
(10933, 1007, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:6:\"Museo \";}s:2:\"fr\";a:1:{s:4:\"text\";s:7:\" Musée\";}}}'),
(10934, 1007, 'additional_info', 'a:2:{s:13:\"accessibility\";a:2:{s:5:\"label\";s:5:\"Bassa\";s:5:\"value\";s:1:\"1\";}s:9:\"date_text\";a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:265:\"1 ottobre - 31 marzo Aperto tutti i giorni dalle 14.30 alle 18.00 Sabato, domenica e festivi anche la mattina dalle 10.30 alle 12.00 1 aprile - 30 giugno Aperto tutti i giorni dalle 15.00 alle 18.30 Sabato, domenica e festivi anche la mattina dalle 10.30 alle 12.00\";}s:2:\"fr\";a:1:{s:4:\"text\";s:296:\"Du 1er octobre au 31 mars : Ouvert tous les jours de 14h30 à 18h00. Samedi, dimanche et jours fériés également ouvert le matin de 10h30 à 12h00. Du 1er avril au 30 juin : Ouvert tous les jours de 15h00 à 18h30. Samedi, dimanche et jours fériés également ouvert le matin de 10h30 à 12h00\";}}}}'),
