(11039, 1019, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:18:\"Museo della Città\";}s:2:\"fr\";a:1:{s:4:\"text\";s:18:\"Musée de la ville\";}}}'),
(11040, 1019, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:256:\"Il Museo della Città di Livorno, situato nel complesso dei Bottini dell’Olio, offre un viaggio attraverso la storia e l’identità culturale della città. Le sue esposizioni permanenti esplorano il legame di Livorno con il mare, l’arte e il commercio\";}s:2:\"fr\";a:1:{s:4:\"text\";s:271:\"Le Musée de la Ville de Livourne, situé dans le complexe des Bottini dell\'Olio, offre un voyage traversant l\'histoire et l\'identité culturelle de la ville. Les poursuites en vue d\'une exposition permanente explorent le jeu de Livourne avec la mer, l\'art et le commerce\";}}}'),
(11041, 1019, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:6:\"Museo \";}s:2:\"fr\";a:1:{s:4:\"text\";s:7:\" Musée\";}}}'),
