(11192, 1036, 'name', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:34:\"Fortezza Vecchia - Centro portuale\";}s:2:\"fr\";a:1:{s:4:\"text\";s:37:\"Vieille forteresse - Centre portuaire\";}}}'),
(11193, 1036, 'description', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:237:\"Vero scrigno di tesori nascosti, questo gioiello architettonico, costruito nel XVI secolo per ordine di Cosimo I De’ Medici, è molto più di una semplice fortificazione militare. Siamo di fronte al vero custode delle radici di Livorno\";}s:2:\"fr\";a:1:{s:4:\"text\";s:249:\"Véritable écrin de trésors cachés, ce joyau architectural, construit au XVIe siècle sur ordre de Cosme Ier de Médicis, est bien plus qu\'une simple fortification militaire. Nous nous trouvons devant le véritable gardien des racines de Livourne\";}}}'),
(11194, 1036, 'subtype', 'a:1:{s:11:\"translation\";a:2:{s:2:\"it\";a:1:{s:4:\"text\";s:10:\"Monumento \";}s:2:\"fr\";a:1:{s:4:\"text\";s:9:\" Monument\";}}}'),
