(901, 1, '2026-01-12 16:19:37', '2026-01-12 15:19:37', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Bassa\",\"value\":\"1\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"n.p.\"},\"fr\":{\"text\":\"n.p.\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Oratorio di San Rocco\"},\"fr\":{\"text\":\"Oratoire Saint-Roch\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Costruito nel 1599, l\'oratorio era situato fuori dalle mura cittadine. Era la sede della confraternita dei Santi Rocco e Sebastiano, incaricata di portare i sacramenti di notte alla popolazione che non poteva accedere ai servizi della cattedrale.\"},\"fr\":{\"text\":\"Edifié en 1599, l\'oratoire se situait hors des murs de la ville. Il était le siège de la confrérie de Saint-Roch et Saint-Sébastien, chargée d\'apporter des sacrements, la nuit, à une population qui ne pouvait recourir aux services de la cathédral\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"oratorio\"},\"fr\":{\"text\":\"oratoire\"}}},\"contacts\":{\"telephone\":\"n.p.\",\"email\":\"n.p.\",\"website\":\"https://archives-map.culture.gouv.fr/archive/recherche/simple/n:19?RECH_S=PA00099069&RECH_DocumentsNumerises=0&Archives.RECH_Valid=&type=simple\"},\"position\":{\"address\":\"Cardinal-Fesch (rue), Ajaccio\",\"latitude\":41.922,\"longitude\":8.738,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Cardinal-Fesch (rue), Ajaccio\",\"short_name\":\"Cardinal-Fesch (rue), Ajaccio\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Cardinal-Fesch (rue), Ajaccio\",\"geometry\":{\"location\":{\"lat\":41.922,\"lng\":8.738},\"location_type\":\"\",\"viewport\":{\"northeast\":{\"lat\":41.922,\"lng\":8.738},\"southwest\":{\"lat\":41.922,\"lng\":8.738}}},\"navigation_points\":[{\"location\":{\"latitude\":41.922,\"longitude\":8.738}}],\"place_id\":\"\",\"plus_code\":{\"compound_code\":\"\",\"global_code\":\"\"},\"types\":[]},\"formatted_address\":\"Cardinal-Fesch (rue), Ajaccio\"}}} /-->', 'Oratorio di San Rocco', '', 'publish', 'closed', 'closed', '', 'oratorio-di-san-rocco', '', '', '2026-01-12 16:19:37', '2026-01-12 15:19:37', '', 0, 'https://gestionale.qualitymade.eu/qzr_object/oratorio-di-san-rocco/', 0, 'qzr_object', '', 0),
(902, 1, '2026-01-12 16:19:37', '2026-01-12 15:19:37', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Bassa\",\"value\":\"1\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"n.p.\"},\"fr\":{\"text\":\"n.p.\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Cittadella\"},\"fr\":{\"text\":\"Citadelle\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Nel 1487 e nel 1488, i genovesi costruirono un mastio sulla punta del promontorio dove sorge l\'attuale cittadella. La cittadella stessa fu in gran parte costruita tra il 1554 e il 1559, ad opera del maresciallo de Termes e del suo successore, Giordano Orsini\"},\"fr\":{\"text\":\"En 1487 et 1488, les Gênois bâtirent un donjon au bout du promontoire de la citadelle actuelle. Celle-ci fut édifiée pour l\'essentiel de 1554 à 1559, oeuvre du maréchal de Termes et de son successeur, Giordano Orsini\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"cattadella\"},\"fr\":{\"text\":\"citadelle\"}}},\"contacts\":{\"telephone\":\"n.p.\",\"email\":\"n.p.\",\"website\":\"https://archives-map.culture.gouv.fr/archive/recherche/simple/n:19?RECH_S=PA00099062&RECH_DocumentsNumerises=0&Archives.RECH_Valid=&type=simple\"},\"position\":{\"address\":\"Ajaccio\",\"latitude\":41.917,\"longitude\":8.74,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Ajaccio\",\"short_name\":\"Ajaccio\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Ajaccio\",\"geometry\":{\"location\":{\"lat\":41.917,\"lng\":8.74},\"location_type\":\"\",\"viewport\":{\"northeast\":{\"lat\":41.917,\"lng\":8.74},\"southwest\":{\"lat\":41.917,\"lng\":8.74}}},\"navigation_points\":[{\"location\":{\"latitude\":41.917,\"longitude\":8.74}}],\"place_id\":\"\",\"plus_code\":{\"compound_code\":\"\",\"global_code\":\"\"},\"types\":[]},\"formatted_address\":\"Ajaccio\"}}} /-->', 'Cittadella', '', 'publish', 'closed', 'closed', '', 'cittadella', '', '', '2026-01-21 18:14:25', '2026-01-21 17:14:25', '', 0, 'https://gestionale.qualitymade.eu/qzr_object/cittadella/', 0, 'qzr_object', '', 0);
