(907, 1, '2026-01-12 16:19:37', '2026-01-12 15:19:37', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Bassa\",\"value\":\"1\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"n.p.\"},\"fr\":{\"text\":\"n.p.\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Tomba dello scultore Maestracci\"},\"fr\":{\"text\":\"Tombeau du sculpteur Maestracci\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"La tomba fu realizzata dal pittore e scultore corso Maestracci nel 1928; moriÌ nel 1976. La tomba ha tre livelli separati da cornici ed è sormontata da una croce.\"},\"fr\":{\"text\":\"Le tombeau a été édifié par le peintre et sculpteur insulaire Maestracci, en 1928, qui est décédé en 1976. Le tombeau comporte trois niveaux séparés par des corniches. Il est sommé d\'une croix\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"tomba\"},\"fr\":{\"text\":\"tombeau\"}}},\"contacts\":{\"telephone\":\"n.p.\",\"email\":\"n.p.\",\"website\":\"https://archives-map.culture.gouv.fr/archive/recherche/simple/n:19?RECH_S=PA00099221\\u0026RECH_DocumentsNumerises=0\\u0026Archives.RECH_Valid=\\u0026type=simple\"},\"position\":{\"address\":\"Occhiatana\",\"latitude\":42.574,\"longitude\":9.009,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Occhiatana\",\"short_name\":\"Occhiatana\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code