(911, 1, '2026-01-12 16:19:37', '2026-01-12 15:19:37', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Bassa\",\"value\":\"1\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"n.p.\"},\"fr\":{\"text\":\"n.p.\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Casa conosciuta come Palazzo Nazionale\"},\"fr\":{\"text\":\"Maison dite Palais National\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Casa quadrata costruita all\'inizio del XVII secolo (1600-1630) per fungere da residenza del luogotenente rappresentante del governo genovese a Corte. Dal 1755 al 1769, Pasquale Paoli vi stabiliÌ la sede del Parlamento della Corsica indipendente.\"},\"fr\":{\"text\":\"Maison carrée construite au début du 17e siècle (1600-1630) pour servir de résidence au lieutenant représentant à Corte le gouvernement de Gênes. De 1755 à 1769, Pascal Paoli y établit le siège du Parlement de la Corse indépendante\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"casa\"},\"fr\":{\"text\":\"maison\"}}},\"contacts\":{\"telephone\":\"n.p.\",\"email\":\"n.p.\",\"website\":\"https://archives-map.culture.gouv.fr/archive/recherche/simple/n:19?RECH_S=PA00099195&RECH_DocumentsNumerises=0&Archives.RECH_Valid=&type=simple\"},\"position\":{\"address\":\"Poilu (place du), Corte\",\"latitude\":42.305,\"longitude\":9.149,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Poilu (place du), Corte\",\"short_name\":\"Poilu (place du), Corte\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]}