(996, 45, '2026-01-12 16:19:41', '2026-01-12 15:19:41', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Alta\",\"value\":\"3\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"sempre aperto\"},\"fr\":{\"text\":\"toujours ouvert\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"La Cattedrale di Nostra Signora Assunta\"},\"fr\":{\"text\":\"La cathédrale Notre-Dame de l\'Assomption\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"La Cattedrale fu costruita nel XVI secolo per sostituire l\'antica struttura, posta sul promontorio del Priamar, che fu abbattuta da Genova per costruire una fortezza. La nuova Cattedrale fu costruita sull\'area della Chiesa di San Francesco\"},\"fr\":{\"text\":\"La cathédrale fut construite au XVIe siècle pour remplacer l\'ancienne structure, située sur le promontoire de Priamar, qui avait été démolie par Gênes pour y construire une forteresse. La nouvelle cathédrale fut érigée sur l\'emplacement de l\'église Saint-François\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"Monumento \"},\"fr\":{\"text\":\" Monument\"}}},\"contacts\":{\"telephone\":\"3270281083\",\"email\":\"visitasistina@diocesisavona.it\",\"website\":\"https://www.visitsavona.com/it/cosa-vedere-a-savona/edifici-religiosi/cattedrale-nostra-signora-assunta\"},\"position\":{\"address\":\"Savona: Piazza del Duomo\",\"latitude\":44.3034046,\"longitude\":8.4743315,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Savona: Piazza del Duomo\",\"short_name\":\"Savona: Piazza del Duomo\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Savona: Piazza del Duomo\",\"geometry\":{\"location\":{\"lat\":44.3034046,\"lng\":8.4743315},\"location_type\":\"\",\"viewport\":{\"northeast\":{\"lat\":44.3034046,\"lng\":8.4743315},\"southwest\":{\"lat\":44.3034046,\"lng\":8.4743315}}},\"navigation_points\":[{\"location\":{\"latitude\":44.3034046,\"longitude\":8.4743315}}],\"place_id\":\"\",\"plus_code\":{\"compound_code\":\"\",\"global_code\":\"\"},\"types\":[]},\"formatted_address\":\"Savona: Piazza del Duomo\"},\"video\":\"https://www.youtube.com/watch?v=JxCYIFumuRU\",\"gallery\":[{\"id\":2899,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/05_IL_DUOMO-media-9a2dd926-query.d024cc11.webp\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2900,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Savona_Cattedrale_dellAssunta_pulpit_02.jpg\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2901,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Savona_Cattedrale_dellAssunta_20.jpg\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2902,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Savona_Cathedral_2010_2.jpg\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2903,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Savona_Cathedral_altar_2010.jpg\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2904,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Savona_Cathedral_dome_2010.jpg\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title