(1004, 47, '2026-01-12 16:19:41', '2026-01-12 15:19:41', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"name\":{\"translation\":{\"it\":{\"text\":\"Osservatorio astronomico di Perinaldo \\u0022G.D.Cassini\\u0022\"},\"fr\":{\"text\":\"Observatoire astronomique de Perinaldo « G.D.Cassini »\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Perinaldo, “borgo stellare” certificato Bandiera Arancione, è noto agli appassionati di astronomia per Giovanni Domenico Cassini (1625-1712), “astronomo del Re Sole” che scoprì quattro satelliti di Saturno (Giapeto, Rea, Dione e Teti)\"},\"fr\":{\"text\":\"Perinaldo, village labellisé « Pavillon Orange », est connu des passionnés d’astronomie pour Giovanni Domenico Cassini (1625-1712), « l’astronome du Roi Soleil » qui a découvert quatre des satellites de Saturne (Japet, Rhéa, Dioné et Téthys)\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"Museo \"},\"fr\":{\"text\":\"Musée\"}}},\"position\":{\"address\":\"Piazza Mons Antonio Rossi, 1, 18032 Perinaldo IM, Italia\",\"latitude\":43.8668572,\"longitude\":7.6736057,\"data\":{\"address_components\":[{\"long_name\":\"1\",\"short_name\":\"1\",\"types\":[\"street_number\"]},{\"long_name\":\"Piazza Mons Antonio Rossi\",\"short_name\":\"Piazza Mons Antonio Rossi\",\"types\":[\"route\"]},{\"long_name\":\"Perinaldo\",\"short_name\":\"Perinaldo\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"Perinaldo\",\"short_name\":\"Perinaldo\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"Provincia di Imperia\",\"short_name\":\"IM\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"Liguria\",\"short_name\":\"Liguria\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"Italia\",\"short_name\":\"IT\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"18032\",\"short_name\":\"18032\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Piazza Mons Antonio Rossi, 1, 18032 Perinaldo IM, Italia\",\"geometry\":{\"bounds\":{\"northeast\":{\"lat\":43.8669338,\"lng\":7.673711399999999},\"southwest\":{\"lat\":43.8667806,\"lng\":7.6735001}},\"location\":{\"lat\":43.8668572,\"lng\":7.6736057},\"location_type\":\"ROOFTOP\",\"viewport\":{\"northeast\":{\"lat\":43.8682650302915,\"lng\":7.674954730291501},\"southwest\":{\"lat\":43.8655670697085,\"lng\":7.672256769708497}}},\"navigation_points\":[{\"location\":{\"latitude\":43.8669902,\"longitude\":7.6736509}}],\"place_id\":\"ChIJ7X0Cge2MzRIR2R2FtrC9sBE\",\"types\":[\"premise\",\"street_address\"]},\"formatted_address\":\"Piazza Mons Antonio Rossi, 1, 18032 Perinaldo IM, Italia\"},\"contacts\":{\"website\":\"https://www.flyorbita.com/\",\"telephone\":\"0039 351 789 4592\",\"email\":\"osservatorioperinaldo@yahoo.com\"},\"video\":\"https://www.youtube.com/watch?v=Jdl7uXevtLU\",\"gallery\":[{\"id\":2951,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Picture18-1.png\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2952,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Picture19-1.png\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2953,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Picture20-1.png\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"},{\"id\":2954,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/Picture21-2.png\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"}]}} /-->', 'Osservatorio astronomico di Perinaldo \"G.D.Cassini\"', '', 'publish', 'closed', 'closed', '', 'osservatorio-astronomico-di-perinaldo-g-d-cassini', '', '', '2026-02-06 10:00:05', '2026-02-06 09:00:05', '', 0, 'https://gestionale.qualitymade.eu/qzr_object/osservatorio-astronomico-di-perinaldo-g-d-cassini/', 0, 'qzr_object', '', 0),
