(1015, 52, '2026-01-12 16:19:41', '2026-01-12 15:19:41', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Bassa\",\"value\":\"1\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"sempre aperto\"},\"fr\":{\"text\":\"toujours ouvert\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Mulino Fenicio\"},\"fr\":{\"text\":\"Moulin Phénicien\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Mulino a pale interne definito mulino fenicio per la tecnica costruttiva nata in Medio Oriente. Ne esistono solo altri 2 esemplari nel resto del mondo\"},\"fr\":{\"text\":\"Le moulin à lames internes, également appelé moulin phénicien, est un modèle de construction originaire du Moyen-Orient. Il n\'en existe que deux autres exemplaires dans le monde\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"Monumento \"},\"fr\":{\"text\":\" Monument\"}}},\"contacts\":{\"telephone\":\"n.p.\",\"email\":\"museodelsantuario@operesociali.it\",\"website\":\"n.p.\"},\"position\":{\"address\":\"Via delle Chiesa, 17022 Verezzi\",\"latitude\":44.1691833,\"longitude\":8.3089046,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Via delle Chiesa, 17022 Verezzi\",\"short_name\":\"Via delle Chiesa, 17022 Verezzi\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Via delle Chiesa, 17022 Verezzi\",\"geometry\":{\"locatio