(1016, 53, '2026-01-12 16:19:41', '2026-01-12 15:19:41', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"name\":{\"translation\":{\"it\":{\"text\":\"Museo del Mare\"},\"fr\":{\"text\":\"Musée de la Mer\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Nel museo viene raccontata con modelli, attrezzi usati dai \\u0022maestri d\'ascia\\u0022 e progetti, oltre che con dipinti di velieri costruiti sulla spiaggia varazzino, la storia della cantieristica navale dall\'epoca dei Romani fino agli anni \'90\"},\"fr\":{\"text\":\"Le musée retrace, à l\'aide de maquettes, d\'outils utilisés par les « maîtres charpentiers » et de projets, ainsi que de peintures de voiliers construits sur la plage de Varazzino, l\'histoire de la construction navale depuis l\'époque romaine jusqu\'aux années 90\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"Museo \"},\"fr\":{\"text\":\" Musée\"}}},\"contacts\":{\"website\":\"https://marinadivarazze.it/tag/museo-del-mare/\",\"telephone\":\"0039347 5565942 -0039340 5445335- 0039338 4416005\",\"email\":\"museonavalevarazze@libero.it\"},\"additional_info\":{\"date_text\":{\"translation\":{\"it\":{\"text\":\"Sabato, domenica e festivi 10-12 15-18\"},\"fr\":{\"text\":\"Samedi, dimanche et jours fériés 10h-12h 15h-18h\"}}},\"accessibility\":{\"label\":\"Alta\",\"value\":\"3\"}},\"video\":\"https://www.youtube.com/watch?v=fEPsW5EEJ_A\",\"gallery\":[{\"id\":3039,\"url\":\"https://gestionale.qualitymade.eu/wp-content/uploads/2026/01/MuseoDelMare-800x516-1.jpg\",\"focalPoint\":{\"x\":0.5,\"y\":0.5},\"alt\":\"\",\"title\":\"\",\"caption\":\"\"}],\"position\":{\"address\":\"Via dei Tornitori, 9, 17019 Varazze SV, Italia\",\"latitude\":44.3549447,\"longitude\":8.5669336,\"data\":{\"address_components\":[{\"long_name\":\"9\",\"short_name\":\"9\",\"types\":[\"street_number\"]},{\"long_name\":\"Via dei Tornitori\",\"short_name\":\"Via dei Tornitori\",\"types\":[\"route\"]},{\"long_name\":\"Varazze\",\"short_name\":\"Varazze\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"Varazze\",\"short_name\":\"Varazze\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"Provincia di Savona\",\"short_name\":\"SV\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"Liguria\",\"short_name\":\"Liguria\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"Italia\",\"short_name\":\"IT\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"17019\",\"short_name\":\"17019\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Via dei Tornitori, 9, 17019 Varazze SV, Italia\",\"geometry\":{\"location\":{\"lat\":44.3549447,\"lng\":8.5669336},\"location_type\":\"ROOFTOP\",\"viewport\":{\"northeast\":{\"lat\":44.3560447302915,\"lng\":8.568180830291503},\"southwest\":{\"lat\":44.3533467697085,\"lng\":8.565482869708498}}},\"navigation_points\":[{\"location\":{\"latitude\":44.3544468,\"longitude\":8.5667092},\"restricted_travel_modes\":[\"WALK\"]},{\"location\":{\"latitude\":44.3549335,\"longitude\":8.5669603},\"restricted_travel_modes\":[\"DRIVE\"]}],\"place_id\":\"ChIJgQ774zMf0xIRKP8E0R-3sBs\",\"types\":[\"street_address\",\"subpremise\"]},\"formatted_address\":\"Via dei Tornitori, 9, 17019 Varazze SV, Italia\"}}} /-->', 'Museo del Mare', '', 'publish', 'closed', 'closed', '', 'museo-del-mare', '', '', '2026-02-06 10:01:32', '2026-02-06 09:01:32', '', 0, 'https://gestionale.qualitymade.eu/qzr_object/museo-del-mare/', 0, 'qzr_object', '', 0);
