(1216, 230, '2026-01-12 16:20:05', '2026-01-12 15:20:05', '<!-- wp:qzrstudio/object-info {\"fields\":{\"name\":{\"translation\":{\"it\":{\"text\":\"GUSTU NATURA\"},\"fr\":{\"text\":\"GUSTU NATURA\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Gastronomia artigianale\"},\"fr\":{\"text\":\"gastronomie artisanale\"}}},\"type\":{\"label\":\"Azienda\",\"value\":\"society\"},\"contacts\":{\"telephone\":\"0033643831041\",\"email\":\"contact@gustunatura.com\",\"website\":\"https://www.gustunatura.com/\"},\"additional_info\":{\"municipality\":\"Sartène\",\"address\":\"PIANOLI ROUTE DE LA CASTAGNA 20100 SARTENE\",\"piva\":\"FR60808291801\"},\"position\":{\"address\":\"Sartène, PIANOLI ROUTE DE LA CASTAGNA 20100 SARTENE\",\"latitude\":41.62948433,\"longitude\":8.981591346,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Sartène, PIANOLI ROUTE DE LA CASTAGNA 20100 SARTENE\",\"short_name\":\"Sartène, PIANOLI ROUTE DE LA CASTAGNA 20100 SARTENE\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Sartène, PIANOLI ROUTE DE LA CASTAGNA 20100 SARTENE\",\"geometry\":{\"location\":{\"lat\":41.62948433,\"lng\":8.981591346},\"location_type\":\"\",\"viewport\":{\"northeast\":{\"lat\":41.62948433,\"lng\":8.981591346},\"southwest\":{\"lat\":41.62948433,\"lng\":8.981591346}}},\"navigation_points\":[{\"location\":{\"latitude\":41.62948433,\"longitude\":8.981591346}}],\"place_id\":\"\",\"plus_code\"