(2126, 237, '2026-01-19 16:29:26', '2026-01-19 15:29:26', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Media\",\"value\":\"2\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"\"},\"fr\":{\"text\":\"\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Punto Sardine\"},\"fr\":{\"text\":\"Pointe des sardineaux\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Un luogo di relax in riva al mare con una passeggiata lungo la costa e due elementi storici: * un bunker della seconda guerra mondiale (la costa fu il luogo dello sbarco del 15 agosto 1944) * una peschiera risalente all\'epoca romana\"},\"fr\":{\"text\":\"Un lieu de détente en bord de mer, avec une promenade le long du littoral et deux sites historiques : * un bunker de la Seconde Guerre mondiale (la côte fut le lieu du débarquement du 15 août 1944) * un étang à poissons datant de l’époque romaine\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"altro \"},\"fr\":{\"text\":\" autre\"}}},\"contacts\":{\"telephone\":\"04 94 55 75 55\",\"email\":\"contact@sainte-maxime.com\",\"website\":\"https://www.sainte-maxime.com/fr/loisirs/la-pointe-des-sardinaux-4613965/\"},\"position\":{\"address\":\"1 avenue du Général Touzet du Vigier Sainte Maxime\",\"latitude\":43.3188732,\"longitude\":6.6639164,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"1 avenue du Général Touzet du Vigier Sainte Maxime\",\"short_name\":\"1 avenue du Général Touzet du Vigier Sainte Maxime\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"1 avenue du Général Touzet du Vigier Sainte Maxime\",\"geometry\":{\"location\":{\"lat\":43.3188732,\"lng\":6.6639164},\"location_type\":\"\",\"viewport\":{\"northeast\":{\"lat\":43.3188732,\"lng\":6.6639164},\"southwest\":{\"lat\":43.3188732,\"lng\":6.6639164}}},\"navigation_points\":[{\"location\":{\"latitude\":43.3188732,\"longitude\":6.6639164}}],\"place_id\":\"\",\"plus_code\":{\"compound_code\":\"\",\"global_code\":\"\"},\"types\":[]},\"formatted_address\":\"1 avenue du Général Touzet du Vigier Sainte Maxime\"},\"video\":\"https://www.youtube.com/watch?v=hPsi9s3xQXs\"}} /-->', 'Punto Sardine', '', 'inherit', 'closed', 'closed', '', '844-autosave-v1', '', '', '2026-01-19 16:29:26', '2026-01-19 15:29:26', '', 844, 'https://gestionale.qualitymade.eu/?p=2126', 0, 'revision', '', 0),
