(2370, 237, '2026-01-20 15:48:10', '2026-01-20 14:48:10', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Bassa\",\"value\":\"1\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"n.p.\"},\"fr\":{\"text\":\"n.p.\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Palazzo Fesch\"},\"fr\":{\"text\":\"Palais Fesch\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"Costruito per ordine del cardinale Fesch a partire dal 1827, il palazzo fu completato intorno al 1837. Caseneuve, l\'architetto del governo, fu responsabile del progetto della sala di lettura. Frasseto eseguiÌ i progetti del cardinale.\"},\"fr\":{\"text\":\"Construit par ordre du cardinal Fesch à partir de 1827, le palais fut achevé vers 1837. Caseneuve, architecte du gouvernement, fut chargé de l\'aménagement de la salle de lecture. Frasseto fut l\'exécuteur des projets du cardinal\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"palazzo, biblioteca\"},\"fr\":{\"text\":\"palais,bibliothèque\"}}},\"contacts\":{\"telephone\":\"n.p.\",\"email\":\"n.p.\",\"website\":\"https://archives-map.culture.gouv.fr/archive/recherche/simple/n:19?RECH_S=PA00099071\\u0026RECH_DocumentsNumerises=0\\u0026Archives.RECH_Valid=\\u0026type=simple\"},\"position\":{\"address\":\"Cardinal-Fesch (rue) 48 bis, Ajaccio\",\"latitude\":41.922,\"longitude\":8.739,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Cardinal-Fesch (rue) 48 bis, Ajaccio\",\"short_name\":\"Cardinal-Fesch (rue) 48 bis, Ajaccio\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"postal_code\"]}],\"formatted_address\":\"Cardinal-Fesch (rue) 48 bis, Ajaccio\",\"geometry\":{\"location\":{\"lat\":41.922,\"lng\":8.739},\"location_type\":\"\",\"viewport\":{\"northeast\":{\"lat\":41.922,\"lng\":8.739},\"southwest\":{\"lat\":41.922,\"lng\":8.739}}},\"navigation_points\":[{\"location\":{\"latitude\":41.922,\"longitude\":8.739}}],\"place_id\":\"\",\"plus_code\":{\"compound_code\":\"\",\"global_code\":\"\"},\"types\":[]},\"formatted_address\":\"Cardinal-Fesch (rue) 48 bis, Ajaccio\"},\"video\":\"https://www.youtube.com/watch?v=twVWu3hy6yU\"}} /-->', 'Palazzo Fesch', '', 'inherit', 'closed', 'closed', '', '889-autosave-v1', '', '', '2026-01-20 15:48:10', '2026-01-20 14:48:10', '', 889, 'https://gestionale.qualitymade.eu/?p=2370', 0, 'revision', '', 0),
