(2783, 237, '2026-01-22 14:04:14', '2026-01-22 13:04:14', '<!-- wp:qzrstudio/object-info {\"fields\":{\"type\":{\"label\":\"POI\",\"value\":\"poi\"},\"additional_info\":{\"accessibility\":{\"label\":\"Alta\",\"value\":\"3\"},\"date_text\":{\"translation\":{\"it\":{\"text\":\"n.p.\"},\"fr\":{\"text\":\"n.p.\"}}}},\"name\":{\"translation\":{\"it\":{\"text\":\"Chiesa Russa ortodossa\"},\"fr\":{\"text\":\"Église orthodoxe russe\"}}},\"description\":{\"translation\":{\"it\":{\"text\":\"La chiesa ortodossa, ancora oggi aperta ai fedeli, si trova poco distante dal CasinoÌ, tra la chiesa scozzese e quella di San Giovanni Battista, è formata da quattro arcate laterali con cinque cupole sovrastanti il ??telo azzurro\"},\"fr\":{\"text\":\"L\'église orthodoxe, toujours ouverte aux fidèles, est située non loin du Casino, entre l\'église écossaise et celle de Saint-Jean-Baptiste. Elle est formée de quatre arcades latérales surmontées de cinq coupoles recouvrant un voile bleu\"}}},\"subtype\":{\"translation\":{\"it\":{\"text\":\"Monumento \"},\"fr\":{\"text\":\" Monument\"}}},\"contacts\":{\"telephone\":\"0184-531807\",\"email\":\"n.p.\",\"website\":\"https://www.info-sanremo.com/chiesa-russa.html\"},\"position\":{\"address\":\"Via Nuvoloni 2 – 18038 Sanremo\",\"latitude\":43.8145874,\"longitude\":7.7704216,\"data\":{\"address_components\":[{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"street_number\"]},{\"long_name\":\"Via Nuvoloni 2 – 18038 Sanremo\",\"short_name\":\"Via Nuvoloni 2 – 18038 Sanremo\",\"types\":[\"route\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"locality\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_3\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_2\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"administrative_area_level_1\",\"political\"]},{\"long_name\":\"\",\"short_name\":\"\",\"types\":[\"country\",\"political\"]},{\